import {
    RichBlockEditor, type RichBlockEditorProps,
} from "./editor/rich-block-editor";
import {
    useEffect, useId, useRef, useState, type ComponentProps,
    type ReactNode,
} from "react";
import { Button } from "./button";
import { Textarea } from "./textarea";
import { cn } from "./utils";
import type { BlockKind, BlockEditorBlock } from "./editor/legacy-types";

type LegacyBlockEditorProps = Omit<
    ComponentProps<"section">, "children" | "onChange"
> & {
    label: string;
    blocks: readonly BlockEditorBlock[];
    onBlocksChange: (blocks: BlockEditorBlock[]) => void;
    mode?: "legacy";
    value?: never;
    onValueChange?: never;
    createBlockId?: (blocks: readonly BlockEditorBlock[]) => string;
    name?: string;
    description?: string;
    error?: string;
    disabled?: boolean;
    appearance?: "panel" | "plain";
};

type BlockDocumentProps = Omit<
    ComponentProps<"section">, "children"
> & {
    label: string;
    blocks: readonly BlockEditorBlock[];
    emptyMessage?: string;
};

type StructureChange = {
    before: BlockEditorBlock[];
    after: BlockEditorBlock[];
};

const kindLabels: Record<BlockKind, string> = {
    paragraph: "문단",
    heading: "제목",
    subheading: "소제목",
    bullet: "글머리 목록",
    number: "번호 목록",
    quote: "인용",
    code: "코드",
};
const structureHistoryLimit = 50;

function checkBlocks(blocks: readonly BlockEditorBlock[]) {
    if (!Array.isArray(blocks)) {
        throw new TypeError("BlockEditor blocks must be an array.");
    }
    const ids = new Set<string>();
    for (const block of blocks) {
        if (!block || typeof block.id !== "string" ||
            !block.id.trim() || ids.has(block.id) ||
            !Object.hasOwn(kindLabels, block.kind) ||
            typeof block.text !== "string") {
            throw new Error(
                "BlockEditor blocks need unique IDs, kinds, and text.",
            );
        }
        ids.add(block.id);
    }
}

function nextBlockId(blocks: readonly BlockEditorBlock[]) {
    const ids = new Set(blocks.map((block) => block.id));
    let sequence = blocks.length + 1;
    while (ids.has(`block-${sequence}`)) sequence += 1;
    return `block-${sequence}`;
}

function sameStructure(
    left: readonly BlockEditorBlock[], right: readonly BlockEditorBlock[],
) {
    return left.length === right.length && left.every((block, index) =>
        block.id === right[index].id && block.kind === right[index].kind
    );
}

function restoreStructure(
    target: readonly BlockEditorBlock[], current: readonly BlockEditorBlock[],
) {
    const currentById = new Map(current.map((block) => [block.id, block]));
    return target.map((block) => ({
        ...(currentById.get(block.id) ?? block), kind: block.kind,
    }));
}

function LegacyBlockEditor({
    mode: _mode, value: _value, onValueChange: _onValueChange,
    label,
    blocks,
    onBlocksChange,
    createBlockId = nextBlockId,
    name,
    description,
    error,
    disabled = false,
    appearance = "panel",
    className,
    ...props
}: LegacyBlockEditorProps) {
    const titleId = useId();
    const descriptionId = useId();
    const errorId = useId();
    const inputs = useRef(new Map<string, HTMLTextAreaElement>());
    const addButton = useRef<HTMLButtonElement>(null);
    const pendingFocus = useRef<{ id: string | null } | null>(null);
    const history = useRef<{
        past: StructureChange[]; future: StructureChange[];
    }>({ past: [], future: [] });
    const [, redrawHistory] = useState(0);

    if (typeof label !== "string" || !label.trim()) {
        throw new Error("BlockEditor requires a label.");
    }
    if (typeof onBlocksChange !== "function") {
        throw new TypeError("BlockEditor requires onBlocksChange.");
    }
    if (typeof createBlockId !== "function") {
        throw new TypeError("BlockEditor createBlockId must be a function.");
    }
    if (name !== undefined &&
        (typeof name !== "string" || !name.trim())) {
        throw new Error("BlockEditor name must not be empty.");
    }
    if (appearance !== "panel" && appearance !== "plain") {
        throw new RangeError("BlockEditor appearance is not supported.");
    }
    checkBlocks(blocks);

    useEffect(() => {
        const request = pendingFocus.current;
        if (!request) return;
        if (request.id === null && blocks.length === 0) {
            addButton.current?.focus({ preventScroll: true });
            pendingFocus.current = null;
        } else if (request.id && blocks.some((block) =>
            block.id === request.id)) {
            inputs.current.get(request.id)?.focus({ preventScroll: true });
            pendingFocus.current = null;
        }
    }, [blocks]);

    function changeStructure(next: BlockEditorBlock[]) {
        const { past } = history.current;
        if (past.length && !sameStructure(past[past.length - 1].after,
            blocks)) {
            history.current.past = [];
        }
        history.current.past.push({
            before: blocks.map((block) => ({ ...block })),
            after: next.map((block) => ({ ...block })),
        });
        if (history.current.past.length > structureHistoryLimit) {
            history.current.past.shift();
        }
        history.current.future = [];
        redrawHistory((value) => value + 1);
        onBlocksChange(next);
    }

    function replaceBlock(id: string, change: Partial<BlockEditorBlock>) {
        const next = blocks.map((block) =>
            block.id === id ? { ...block, ...change } : block
        );
        if (change.kind !== undefined) changeStructure(next);
        else onBlocksChange(next);
    }

    function insertBlock(afterId?: string) {
        const id = createBlockId(blocks);
        if (typeof id !== "string" || !id.trim() ||
            blocks.some((block) => block.id === id)) {
            throw new Error("BlockEditor createBlockId returned a duplicate ID.");
        }
        const index = afterId === undefined
            ? blocks.length : blocks.findIndex((block) => block.id === afterId) + 1;
        const next = [...blocks];
        next.splice(index, 0, { id, kind: "paragraph", text: "" });
        pendingFocus.current = { id };
        changeStructure(next);
    }

    function removeBlock(id: string, index: number) {
        const next = blocks.filter((block) => block.id !== id);
        pendingFocus.current = { id: next[Math.min(index, next.length - 1)]
            ?.id ?? null };
        changeStructure(next);
    }

    function moveBlock(index: number, offset: number) {
        const next = [...blocks];
        const [block] = next.splice(index, 1);
        next.splice(index + offset, 0, block);
        changeStructure(next);
    }

    const past = history.current.past;
    const future = history.current.future;
    const canUndo = past.length > 0 &&
        sameStructure(past[past.length - 1].after, blocks);
    const canRedo = future.length > 0 &&
        sameStructure(future[future.length - 1].before, blocks);

    function undoStructure() {
        if (!canUndo) return;
        const change = history.current.past.pop()!;
        change.after = blocks.map((block) => ({ ...block }));
        history.current.future.push(change);
        redrawHistory((value) => value + 1);
        onBlocksChange(restoreStructure(change.before, blocks));
    }

    function redoStructure() {
        if (!canRedo) return;
        const change = history.current.future.pop()!;
        change.before = blocks.map((block) => ({ ...block }));
        history.current.past.push(change);
        redrawHistory((value) => value + 1);
        onBlocksChange(restoreStructure(change.after, blocks));
    }

    const describedBy = [
        description ? descriptionId : null,
        error ? errorId : null,
    ].filter(Boolean).join(" ") || undefined;

    return (
        <section {...props} aria-labelledby={titleId}
            data-appearance={appearance}
            data-ui="block-editor"
            className={cn(
                "min-w-0 text-foreground",
                appearance === "panel" &&
                    "rounded-sm border border-border bg-surface",
                className,
            )}>
            {name && <input type="hidden" name={name}
                value={JSON.stringify(blocks)} disabled={disabled} />}
            <div className={cn(
                "grid gap-1 px-[var(--space-4)] py-[var(--space-3)]",
                appearance === "panel" && "border-b border-border",
            )} data-slot="editor-header">
                <div className="flex flex-wrap items-center gap-2">
                    <h3 id={titleId}
                        className="m-0 mr-auto text-base font-semibold">
                        {label}
                    </h3>
                    <Button variant="ghost" disabled={disabled || !canUndo}
                        className="h-8 px-2 text-xs"
                        onClick={undoStructure}>구조 되돌리기</Button>
                    <Button variant="ghost" disabled={disabled || !canRedo}
                        className="h-8 px-2 text-xs"
                        onClick={redoStructure}>구조 다시 실행</Button>
                </div>
                {description && <p id={descriptionId}
                    className="m-0 text-xs text-muted">{description}</p>}
                {error && <p id={errorId} role="alert"
                    className="m-0 text-xs text-danger">{error}</p>}
            </div>
            <ol data-slot="editor-blocks" className={
                "m-0 grid list-none gap-[var(--space-3)] " +
                "p-[var(--space-3)]"
            }>
                {blocks.map((block, index) => (
                    <li key={block.id} data-block-id={block.id}
                        data-slot="editor-block"
                        className={
                            "min-w-0 rounded-sm border border-border " +
                            "bg-surface-subtle p-[var(--space-3)]"
                        }>
                        <div data-slot="block-toolbar" className={
                            "mb-2 flex flex-wrap items-center " +
                            "gap-[var(--space-2)]"
                        }>
                            <span className="mr-auto text-xs text-muted">
                                블록 {index + 1}
                            </span>
                            <select value={block.kind} disabled={disabled}
                                data-ui="native-select"
                                data-appearance="outline"
                                data-presentation="inline"
                                aria-label={`${index + 1}번 블록 형식`}
                                onChange={(event) => replaceBlock(block.id, {
                                    kind: event.currentTarget.value as BlockKind,
                                })}
                                className={
                                    "h-8 rounded-sm border border-border " +
                                    "bg-surface px-2 text-xs text-foreground " +
                                    "focus-visible:outline-2 " +
                                    "focus-visible:outline-focus"
                                }>
                                {Object.entries(kindLabels).map(
                                    ([kind, text]) => <option key={kind}
                                        value={kind}>{text}</option>
                                )}
                            </select>
                            <Button data-slot="surface-action" variant="outline" disabled={disabled ||
                                index === 0} className="h-8 px-2 text-xs"
                                aria-label={`${index + 1}번 블록 위로 이동`}
                                onClick={() => moveBlock(index, -1)}>위로</Button>
                            <Button data-slot="surface-action" variant="outline" disabled={disabled ||
                                index === blocks.length - 1}
                                className="h-8 px-2 text-xs"
                                aria-label={`${index + 1}번 블록 아래로 이동`}
                                onClick={() => moveBlock(index, 1)}>아래로</Button>
                            <Button data-slot="surface-action" variant="outline" disabled={disabled}
                                className="h-8 px-2 text-xs"
                                aria-label={`${index + 1}번 블록 다음에 추가`}
                                onClick={() => insertBlock(block.id)}>추가</Button>
                            <Button data-slot="surface-action" variant="ghost" disabled={disabled}
                                className="h-8 px-2 text-xs"
                                aria-label={`${index + 1}번 블록 삭제`}
                                onClick={() => removeBlock(block.id, index)}>
                                삭제
                            </Button>
                        </div>
                        <Textarea value={block.text} disabled={disabled}
                            rows={block.kind === "code" ? 6 : 3}
                            ref={(node) => {
                                if (node) inputs.current.set(block.id, node);
                                else inputs.current.delete(block.id);
                            }}
                            aria-label={
                                `${index + 1}번 ${kindLabels[block.kind]} 내용`
                            }
                            aria-describedby={describedBy}
                            aria-invalid={!!error}
                            onChange={(event) => replaceBlock(block.id, {
                                text: event.currentTarget.value,
                            })}
                            className={cn(
                                "min-h-20 resize-y bg-surface",
                                block.kind === "code" && "font-mono",
                            )} />
                    </li>
                ))}
            </ol>
            <div className="px-[var(--space-3)] pb-[var(--space-3)]"
                data-slot="editor-footer">
                <Button ref={addButton} data-slot="surface-action" variant="outline"
                    disabled={disabled} onClick={() => insertBlock()}>
                    블록 추가
                </Button>
            </div>
        </section>
    );
}

function BlockDocument({
    label, blocks, emptyMessage = "내용이 없습니다.", className, ...props
}: BlockDocumentProps) {
    if (typeof label !== "string" || !label.trim()) {
        throw new Error("BlockDocument requires a label.");
    }
    checkBlocks(blocks);

    const content: ReactNode[] = [];
    let index = 0;
    while (index < blocks.length) {
        const block = blocks[index];
        if (block.kind === "bullet" || block.kind === "number") {
            const kind = block.kind;
            const items: ReactNode[] = [];
            while (index < blocks.length && blocks[index].kind === kind) {
                const item = blocks[index++];
                items.push(<li key={item.id}
                    className="whitespace-pre-wrap break-words">
                    {item.text}
                </li>);
            }
            content.push(kind === "bullet"
                ? <ul key={block.id} className="m-0 grid gap-1 pl-5">
                    {items}</ul>
                : <ol key={block.id} className="m-0 grid gap-1 pl-5">
                    {items}</ol>);
            continue;
        }
        if (block.kind === "heading") {
            content.push(<h2 key={block.id}
                className="m-0 break-words text-xl font-semibold">
                {block.text}</h2>);
        } else if (block.kind === "subheading") {
            content.push(<h3 key={block.id}
                className="m-0 break-words text-lg font-semibold">
                {block.text}</h3>);
        } else if (block.kind === "quote") {
            content.push(<blockquote key={block.id}
                className={
                    "m-0 border-l-2 border-accent pl-3 " +
                    "whitespace-pre-wrap break-words text-muted"
                }>{block.text}</blockquote>);
        } else if (block.kind === "code") {
            content.push(<pre key={block.id} tabIndex={0}
                aria-label="코드 블록"
                className={
                    "m-0 max-w-full overflow-auto rounded-sm border " +
                    "border-border bg-surface-subtle p-3 text-xs"
                }><code>{block.text}</code></pre>);
        } else {
            content.push(<p key={block.id}
                className="m-0 whitespace-pre-wrap break-words">
                {block.text}</p>);
        }
        index += 1;
    }

    return (
        <section {...props} aria-label={label}
            className={cn("grid min-w-0 gap-[var(--space-3)]", className)}>
            {content.length ? content : (
                <p className="m-0 text-sm text-muted">{emptyMessage}</p>
            )}
        </section>
    );
}

type BlockEditorProps = LegacyBlockEditorProps | RichBlockEditorProps;

function BlockEditor(props: BlockEditorProps) {
    if ("mode" in props && props.mode === "rich") {
        if (props.blocks !== undefined || props.onBlocksChange !== undefined) {
            throw new Error("Rich BlockEditor cannot receive legacy blocks.");
        }
        return <RichBlockEditor {...props} />;
    }
    if ("value" in props || "onValueChange" in props || "mode" in props) {
        throw new Error("Rich BlockEditor requires mode=rich and no legacy blocks.");
    }
    return <LegacyBlockEditor {...props as LegacyBlockEditorProps} />;
}

export { BlockDocument, BlockEditor };
export {
    validateRichDocument, extractRichDocumentHeadings, normalizeRichDocument,
} from "./editor/rich-document";
export {
    legacyBlocksToRichDocument, richDocumentToLegacyBlocks,
} from "./editor/legacy-conversion";
export type { RichBlockEditorProps, LegacyBlockEditorProps };
export type {
    RichDocumentValue, RichDocumentHeading, DocumentReference,
} from "./editor/rich-document";
export type {
    BlockDocumentProps, BlockEditorBlock, BlockEditorProps, BlockKind,
};

import {
    useCallback, useEffect, useId, useMemo, useRef, useState,
    type ComponentProps,
} from "react";
import { Extension, type Editor } from "@tiptap/core";
import { EditorContent, useEditor } from "@tiptap/react";
import { BubbleMenu } from "@tiptap/react/menus";
import { createRichExtensions } from "./rich-extensions";
import {
    extractRichDocumentHeadings, validateRichDocument,
    type RichDocumentValue, type RichDocumentHeading, type DocumentReference,
} from "./rich-document";
import { createCommentPlugin, type InlineComment } from "./comment-anchors";
import { InlineFormatToolbar } from "../inline-format-toolbar";
import { InlineCommentLayer } from "../inline-comment-layer";
import { SlashCommandMenu, type SlashCommandItem } from "../slash-command-menu";
import { MentionInput } from "../mention-input";
import { usePortalContainer } from "../foundation/portal-scope";
import { Button } from "../button";
import { cn } from "../utils";

type RichBlockEditorProps = Omit<
    ComponentProps<"section">, "children" | "onChange"
> & {
    mode: "rich";
    label: string;
    value: RichDocumentValue;
    onValueChange: (value: RichDocumentValue) => void;
    blocks?: never;
    onBlocksChange?: never;
    name?: string;
    description?: string;
    error?: string;
    disabled?: boolean;
    appearance?: "panel" | "plain";
    references?: readonly DocumentReference[];
    onOpenReference?: (reference: DocumentReference) => void;
    onHeadingsChange?: (headings: RichDocumentHeading[]) => void;
    comments?: readonly InlineComment[];
    onCommentsChange?: (comments: InlineComment[]) => void;
    onCreateComment?: (range: { from: number; to: number; quote: string }) => void;
    onReply?: (threadId: string, parentId: string | null, content: string) =>
        void | Promise<void>;
};

type SuggestionState = {
    kind: "/" | "@";
    query: string;
    from: number;
    to: number;
};

const bubbleOptions = {
    strategy: "fixed", placement: "top", offset: 8, inline: true,
} as const;
const emptyReferences: readonly DocumentReference[] = [];
const emptyComments: readonly InlineComment[] = [];

const commands: SlashCommandItem[] = [
    { id: "paragraph", label: "문단", keywords: "paragraph" },
    { id: "heading", label: "제목", keywords: "heading" },
    { id: "bullet", label: "글머리 목록", keywords: "bullet list" },
    { id: "number", label: "번호 목록", keywords: "ordered list" },
    { id: "task", label: "체크리스트", keywords: "task" },
    { id: "quote", label: "인용", keywords: "quote" },
    { id: "code", label: "코드", keywords: "code" },
    { id: "table", label: "표", keywords: "table" },
    { id: "callout", label: "콜아웃", keywords: "callout" },
];

function findSuggestion(editor: Editor): SuggestionState | null {
    const { selection } = editor.state;
    if (!selection.empty || !selection.$from.parent.isTextblock ||
        editor.isActive("codeBlock")) return null;
    const before = selection.$from.parent.textBetween(
        0, selection.$from.parentOffset, "\n", "\uFFFC",
    );
    const match = /(?:^|\s)([/@])([^\s/@]*)$/.exec(before);
    if (!match) return null;
    return {
        kind: match[1] as "/" | "@", query: match[2],
        from: selection.from - match[2].length - 1, to: selection.from,
    };
}

function runCommand(editor: Editor, id: string) {
    const chain = editor.chain().focus();
    switch (id) {
        case "paragraph": return chain.setParagraph().run();
        case "heading": return chain.toggleHeading({ level: 2 }).run();
        case "bullet": return chain.toggleBulletList().run();
        case "number": return chain.toggleOrderedList().run();
        case "task": return chain.toggleTaskList().run();
        case "quote": return chain.toggleBlockquote().run();
        case "code": return chain.toggleCodeBlock().run();
        case "table": return chain.insertTable({ rows: 3, cols: 3 }).run();
        case "callout": return chain.wrapIn("callout").run();
    }
}

function RichBlockEditor({
    label, value, onValueChange, name, description, error, disabled = false,
    appearance = "panel", references = emptyReferences, onOpenReference, onHeadingsChange,
    comments = emptyComments, onCommentsChange, onCreateComment, onReply, className,
    mode: _mode, blocks: _blocks, onBlocksChange: _onBlocksChange, ...props
}: RichBlockEditorProps) {
    validateRichDocument(value);
    const descriptionId = useId();
    const host = useRef<HTMLDivElement>(null);
    const latest = useRef({
        onValueChange, onHeadingsChange, onCommentsChange, onOpenReference,
        references,
    });
    latest.current = {
        onValueChange, onHeadingsChange, onCommentsChange, onOpenReference,
        references,
    };
    const referenceViews = useRef(new Set<() => void>());
    const commentPlugin = useMemo(() => createCommentPlugin(comments), []);
    const portal = usePortalContainer();
    const [suggestion, setSuggestion] = useState<SuggestionState | null>(null);
    const [activeIndex, setActiveIndex] = useState(0);
    const [revision, setRevision] = useState(0);
    const [menuPosition, setMenuPosition] = useState({ left: 0, top: 0 });
    const [imageUrl, setImageUrl] = useState("");
    const [imageError, setImageError] = useState("");
    const dismissed = useRef<string | null>(null);
    const keyHandler = useRef<(event: KeyboardEvent) => boolean>(() => false);
    const editor = useEditor({
        extensions: [
            ...createRichExtensions({
                resolve: (kind, id) => latest.current.references.find((item) =>
                    item.kind === kind && item.id === id),
                onOpen: (kind, id) => {
                    const reference = latest.current.references.find((item) =>
                        item.kind === kind && item.id === id);
                    if (reference && !reference.disabled && !reference.inaccessible)
                        latest.current.onOpenReference?.({
                            kind: reference.kind, id: reference.id,
                            label: reference.label,
                        });
                },
                subscribe: (refresh) => {
                    referenceViews.current.add(refresh);
                    return () => { referenceViews.current.delete(refresh); };
                },
            }),
            Extension.create({
                name: "inlineComments",
                addProseMirrorPlugins: () => [commentPlugin.plugin],
            }),
        ],
        content: value.content,
        immediatelyRender: false,
        editable: !disabled,
        editorProps: {
            attributes: {
                role: "textbox", "aria-label": label,
                "aria-multiline": "true",
                class: "min-h-48 outline-none p-3",
            },
            handleKeyDown: (_view, event) => keyHandler.current(event),
            handleDOMEvents: {
                // Skip engine keymaps without canceling the IME's native key.
                // The event flag can precede the engine's composing state.
                keydown: (view, event) => view.composing ||
                    event.isComposing || event.keyCode === 229,
                click: (_view, event) => {
                    const target = event.target instanceof Element
                        ? event.target.closest<HTMLElement>("[data-comment-id]")
                        : null;
                    if (!target) return false;
                    const threads = host.current?.parentElement
                        ?.querySelectorAll<HTMLElement>("[data-inline-thread-id]");
                    const thread = Array.from(threads ?? []).find((item) =>
                        item.dataset.inlineThreadId === target.dataset.commentId);
                    thread?.scrollIntoView({ block: "nearest" });
                    thread?.focus({ preventScroll: true });
                    return false;
                },
            },
            handleClickOn: (_view, _pos, node, _nodePos, event) => {
                if (node.type.name !== "mention") return false;
                event.preventDefault();
                const reference = latest.current.references.find((item) =>
                    item.id === node.attrs.id && item.kind === node.attrs.kind);
                if (!reference || reference.disabled || reference.inaccessible)
                    return true;
                latest.current.onOpenReference?.({
                    kind: node.attrs.kind, id: node.attrs.id,
                    label: reference.label,
                });
                return true;
            },
        },
        onUpdate: ({ editor: current }) => {
            const next: RichDocumentValue = {
                version: 1, content: current.getJSON(),
            };
            latest.current.onValueChange(next);
            latest.current.onHeadingsChange?.(extractRichDocumentHeadings(next));
        },
        onTransaction: ({ editor: current, transaction }) => {
            if (!transaction.docChanged && !transaction.selectionSet) return;
            setRevision((count) => count + 1);
            if (transaction.docChanged) {
                const next = commentPlugin.key.getState(current.state) ?? [];
                latest.current.onCommentsChange?.([...next]);
            }
            const found = findSuggestion(current);
            const signature = found ? JSON.stringify(found) : null;
            if (!found) dismissed.current = null;
            const next = signature === dismissed.current ? null : found;
            setSuggestion((previous) => JSON.stringify(previous) ===
                JSON.stringify(next) ? previous : next);
        },
    });

    useEffect(() => {
        if (!editor) return;
        editor.setEditable(!disabled);
        editor.view.dom.setAttribute("aria-label", label);
        editor.view.dom.setAttribute("aria-invalid", String(Boolean(error)));
        if (description || error) {
            editor.view.dom.setAttribute("aria-describedby", descriptionId);
        } else editor.view.dom.removeAttribute("aria-describedby");
    }, [editor, disabled, label, error, description, descriptionId]);
    useEffect(() => {
        if (!editor) return;
        const canonical = editor.schema.nodeFromJSON(value.content).toJSON();
        if (JSON.stringify(editor.getJSON()) !== JSON.stringify(canonical)) {
            editor.commands.setContent(value.content, {
                emitUpdate: false, errorOnInvalidContent: true,
            });
        }
    }, [editor, value]);
    useEffect(() => {
        if (!editor) return;
        const current = commentPlugin.key.getState(editor.state);
        if (JSON.stringify(current) !== JSON.stringify(comments)) {
            editor.view.dispatch(editor.state.tr.setMeta(commentPlugin.key,
                comments));
        }
    }, [editor, comments, commentPlugin]);
    useEffect(() => {
        if (!editor) return;
        if (suggestion && host.current) {
            const caret = editor.view.coordsAtPos(suggestion.to);
            const box = host.current.getBoundingClientRect();
            const position = {
                left: Math.max(0, Math.min(caret.left - box.left,
                    box.width - 240)), top: caret.bottom - box.top + 4,
            };
            setMenuPosition((current) => current.left === position.left &&
                current.top === position.top ? current : position);
        }
    }, [editor, revision, suggestion]);
    useEffect(() => {
        for (const refresh of referenceViews.current) refresh();
    }, [references]);
    useEffect(() => setActiveIndex(0), [suggestion?.query, suggestion?.kind]);

    const query = suggestion?.query.toLocaleLowerCase() ?? "";
    const commandItems = commands.filter((item) =>
        `${item.label} ${item.keywords}`.toLocaleLowerCase().includes(query));
    const referenceItems = references.filter((item) =>
        !item.disabled && !item.inaccessible &&
        `${item.label} ${item.id}`.toLocaleLowerCase().includes(query));
    function select(item: SlashCommandItem | DocumentReference) {
        if (!editor || !suggestion) return;
        editor.chain().focus().deleteRange(suggestion).run();
        if ("kind" in item) {
            editor.chain().focus().insertContent([
                { type: "mention", attrs: {
                    id: item.id, kind: item.kind, label: item.label,
                } }, { type: "text", text: " " },
            ]).run();
        } else runCommand(editor, item.id);
        setSuggestion(null);
    }
    keyHandler.current = (event) => {
        if (!suggestion || event.isComposing || event.keyCode === 229 ||
            editor?.view.composing) return false;
        const items = suggestion.kind === "/" ? commandItems : referenceItems;
        if (event.key === "Escape") {
            dismissed.current = JSON.stringify(suggestion);
            setSuggestion(null);
            return true;
        }
        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            setActiveIndex((index) => items.length
                ? (index + (event.key === "ArrowDown" ? 1 : -1) +
                    items.length) % items.length : 0);
            return true;
        }
        if (event.key === "Enter" && items[activeIndex]) {
            select(items[activeIndex]);
            return true;
        }
        return false;
    };
    function selectionRange() {
        if (!editor || editor.state.selection.empty) return null;
        const { from, to } = editor.state.selection;
        return { from, to, quote: editor.state.doc.textBetween(from, to, "\n") };
    }
    const shouldShow = useCallback(() => Boolean(editor && !disabled &&
        !editor.state.selection.empty), [editor, disabled]);
    const appendBubbleMenu = useCallback(() =>
        portal instanceof HTMLElement ? portal :
            editor!.view.dom.ownerDocument.body, [portal, editor]);
    const virtualSelection = useCallback(() => {
        if (!editor) return null;
        const selection = editor.view.dom.ownerDocument.getSelection();
        if (!selection?.rangeCount || selection.isCollapsed) return null;
        const range = selection.getRangeAt(0).cloneRange();
        if (!editor.view.dom.contains(range.commonAncestorContainer)) return null;
        return {
            contextElement: editor.view.dom,
            getBoundingClientRect: () => range.getBoundingClientRect(),
            getClientRects: () => range.getClientRects(),
        };
    }, [editor]);
    return <section {...props} aria-label={label} data-slot="rich-block-editor"
        className={cn("grid min-w-0 gap-3", className)}>
        {(description || error) && <p id={descriptionId}
            role={error ? "alert" : undefined} className="text-sm text-muted">
            {error || description}
        </p>}
        {name && <input type="hidden" name={name}
            value={JSON.stringify(value)} disabled={disabled} />}
        <div className="flex flex-wrap items-center gap-2" aria-label="문서 작업">
            <Button className="h-8 px-2 text-xs" disabled={!editor || disabled}
                onClick={() => editor?.chain().focus().undo().run()}>실행 취소</Button>
            <Button className="h-8 px-2 text-xs" disabled={!editor || disabled}
                onClick={() => editor?.chain().focus().redo().run()}>다시 실행</Button>
            <input type="url" aria-label="이미지 URL" value={imageUrl}
                disabled={disabled} placeholder="https://…"
                className="rounded-sm border border-border bg-surface p-2 text-sm"
                onChange={(event) => setImageUrl(event.target.value)} />
            <Button className="h-8 px-2 text-xs" disabled={!editor || disabled || !imageUrl.trim()}
                onClick={() => {
                    if (!/^https?:\/\//i.test(imageUrl)) {
                        setImageError("HTTP 또는 HTTPS 이미지 URL을 입력하세요.");
                        return;
                    }
                    editor?.chain().focus().setImage({ src: imageUrl }).run();
                    setImageUrl(""); setImageError("");
                }}>이미지 삽입</Button>
        </div>
        {imageError && <p role="alert">{imageError}</p>}
        <div ref={host} className={cn("relative min-w-0",
            appearance === "panel" && "rounded-md border border-border")}>
            {editor && <BubbleMenu editor={editor}
                shouldShow={shouldShow}
                appendTo={appendBubbleMenu}
                getReferencedVirtualElement={virtualSelection}
                options={bubbleOptions}>
                <InlineFormatToolbar editor={editor}
                    onComment={onCreateComment ? () => {
                        const range = selectionRange();
                        if (range) onCreateComment(range);
                    } : undefined} />
            </BubbleMenu>}
            <EditorContent editor={editor} className={
                "[&_ul]:list-disc [&_ul]:pl-6 [&_ol]:list-decimal " +
                "[&_ol]:pl-6 [&_h1]:text-2xl [&_h2]:text-xl " +
                "[&_h3]:text-lg [&_td]:border [&_td]:border-border " +
                "[&_th]:border [&_th]:border-border [&_td]:p-2 [&_th]:p-2 " +
                "[&_pre]:bg-surface-subtle [&_pre]:p-3 [&_img]:max-w-full"
            } />
            {suggestion && !disabled && <div className="absolute z-50 w-60"
                style={menuPosition}>
                {suggestion.kind === "/" ?
                    <SlashCommandMenu items={commandItems}
                        activeIndex={activeIndex} onSelect={select} /> :
                    <MentionInput items={referenceItems}
                        activeIndex={activeIndex} onSelect={select} />}
            </div>}
        </div>
        {onCommentsChange && <InlineCommentLayer label="문서 댓글"
            comments={comments} onCommentsChange={onCommentsChange}
            onReply={onReply} disabled={disabled}
            onSelect={(item) => {
                if (item.anchor === "attached") editor?.chain().focus()
                    .setTextSelection({ from: item.from, to: item.to }).run();
            }}
            onReattach={(id) => {
                const range = selectionRange();
                if (range) onCommentsChange(comments.map((item) =>
                    item.id === id ? { ...item, ...range, anchor: "attached" }
                        : item));
            }} />}
    </section>;
}

export { RichBlockEditor };
export type { RichBlockEditorProps };
